import { FormEvent, lazy, Suspense, useEffect, useState } from 'react'
import { Award, Bell, BookOpen, Bookmark, Bot, BriefcaseBusiness, CalendarDays, ChevronRight, ClipboardCheck, FileCheck2, GraduationCap, LayoutDashboard, LogOut, Search, Send, Settings, UserRoundCheck, UsersRound, Wind } from 'lucide-react'
import { api } from './api'

const ImmersiveLandingScene = lazy(() => import('./components/ImmersiveLandingScene').then(module => ({ default: module.ImmersiveLandingScene })))

type User = { id: number; name: string; email: string; employeeId: string; role: string; institution: string; department?: string; jobRole?: string; onboardingComplete?: boolean; profileCompletion?: number; verifiedSkills?: number }
type Toast = { message: string; kind?: 'error' | 'success' }
type Page = 'dashboard' | 'profile' | 'gaps' | 'plan' | 'courses' | 'assessments' | 'mentors' | 'knowledge' | 'certificates' | 'reviews' | 'trainer' | 'manager' | 'admin'
type Options = { institutions: { id: number; name: string; location: string }[]; departments: { id: number; name: string; institutionId: number }[]; jobRoles: { id: number; title: string; domain: string }[]; skills: { id: number; name: string; domain: string }[] }

const suggestedDepartments = ['Meteorology & Climate', 'Ocean Sciences', 'Seismology & Geophysics', 'Atmospheric Observations', 'Earth System Modelling', 'Information Technology & Data Services', 'Research & Innovation', 'Training & Capacity Building', 'Administration & Finance', 'Communications & Knowledge Management']
const suggestedJobRoles = ['Data Analyst', 'Frontend Developer', 'Backend Developer', 'Full-Stack Developer', 'AI/ML Engineer', 'GIS Analyst', 'Research Scientist', 'Meteorologist', 'Oceanographer', 'Climate Data Specialist']
const roleSpecificSkills: Record<string, Options['skills']> = {
  'data analyst': [{ id: -1101, name: 'Data Analysis Fundamentals', domain: 'Data & Digital' }, { id: -1102, name: 'SQL & Data Querying', domain: 'Data & Digital' }, { id: -1103, name: 'Python for Data Analysis', domain: 'Data & Digital' }, { id: -1104, name: 'Data Visualisation', domain: 'Data & Digital' }, { id: -1105, name: 'Statistical Analysis', domain: 'Data & Digital' }, { id: -1106, name: 'Dashboard Design', domain: 'Data & Digital' }, { id: -1107, name: 'Spreadsheet Modelling', domain: 'Data & Digital' }, { id: -1108, name: 'Data Cleaning & Quality', domain: 'Data & Digital' }, { id: -1109, name: 'Data Storytelling', domain: 'Data & Digital' }, { id: -1110, name: 'Machine Learning Fundamentals', domain: 'Data & Digital' }],
  'frontend developer': [{ id: -1201, name: 'HTML & CSS', domain: 'Software Development' }, { id: -1202, name: 'JavaScript & TypeScript', domain: 'Software Development' }, { id: -1203, name: 'React Development', domain: 'Software Development' }, { id: -1204, name: 'UI/UX Fundamentals', domain: 'Software Development' }, { id: -1205, name: 'Web Accessibility', domain: 'Software Development' }, { id: -1206, name: 'Responsive Web Design', domain: 'Software Development' }, { id: -1207, name: 'Git & Version Control', domain: 'Software Development' }, { id: -1208, name: 'API Integration', domain: 'Software Development' }, { id: -1209, name: 'Frontend Testing', domain: 'Software Development' }, { id: -1210, name: 'Web Performance', domain: 'Software Development' }],
}

const icons: Record<Page, typeof LayoutDashboard> = { dashboard: LayoutDashboard, profile: UserRoundCheck, gaps: BriefcaseBusiness, plan: CalendarDays, courses: BookOpen, assessments: ClipboardCheck, mentors: UsersRound, knowledge: Bot, certificates: Award, reviews: FileCheck2, trainer: GraduationCap, manager: UsersRound, admin: Settings }
const labels: Record<Page, { label: string; purpose: string }> = {
  dashboard: { label: 'Dashboard', purpose: 'Your daily learning actions, progress, support, and notifications.' },
  profile: { label: 'My Profile', purpose: 'Keep your personal work details and learning preferences accurate.' },
  gaps: { label: 'My Skill Gaps', purpose: 'Compare your current skills with the competencies your job role requires.' },
  plan: { label: 'Learning Plan', purpose: 'A weekly schedule shaped by your role, priorities, and available time.' },
  courses: { label: 'Courses', purpose: 'Find courses, continue lessons, save useful learning, and track progress.' },
  assessments: { label: 'Assessments', purpose: 'Complete knowledge checks, assignments, and practical evidence for review.' },
  mentors: { label: 'Mentors', purpose: 'Find experts who match your skill gaps, language, and availability.' },
  knowledge: { label: 'Knowledge Hub', purpose: 'Search approved organisational knowledge with cited Prithvi AI answers.' },
  certificates: { label: 'Certificates', purpose: 'View verified competencies, badges, and certificate verification codes.' },
  reviews: { label: 'Evidence Reviews', purpose: 'Review practical evidence and record a clear verification decision.' },
  trainer: { label: 'Trainer Dashboard', purpose: 'Create learning, review practical submissions, and support employees.' },
  manager: { label: 'Manager Dashboard', purpose: 'Review team skill gaps, set priorities, and monitor development progress.' },
  admin: { label: 'Admin Panel', purpose: 'Manage people, organisation structures, role competencies, courses, and reporting.' },
}

function roleKind(role: string) { if (role === 'Employee/Learner') return 'employee'; if (role === 'Trainer') return 'trainer'; if (role.includes('Manager')) return 'manager'; if (role.includes('Administrator') || role.includes('Super')) return 'admin'; return 'expert' }
function Brand() { return <div className="brand"><div className="brand-mark"><Wind size={18} /></div><span>Capacity Connect</span></div> }
function PageHeader({ page, action }: { page: Page; action?: JSX.Element }) { return <header className="page-header"><div><div className="eyebrow">Capacity Connect</div><h1>{labels[page].label}</h1><p>{labels[page].purpose}</p></div>{action}</header> }
function Loading({ error, retry }: { error?: string; retry?: () => void }) { return error ? <div className="empty"><b>We could not load this page.</b><br />{error}<br />{retry && <button className="secondary" onClick={retry}>Try again</button>}</div> : <div className="loader">Loading your workspace…</div> }

function InstitutionNameField({ options, form, update, prefix }: { options: Options; form: any; update: (key: string, value: unknown) => void; prefix: string }) {
  return <label className="field">Institution / organisation (type your own)<input list={`${prefix}-institutions`} value={form.institutionName || ''} onChange={event => { update('institutionName', event.target.value); if (!form.institutionId && options.institutions[0]) update('institutionId', options.institutions[0].id) }} placeholder="Type or choose an institution" required /><datalist id={`${prefix}-institutions`}>{options.institutions.map(item => <option key={item.id} value={item.name} />)}</datalist></label>
}

function RoleDetailsFields({ options, form, update, prefix }: { options: Options; form: any; update: (key: string, value: unknown) => void; prefix: string }) {
  const departments = [...new Set([...suggestedDepartments, ...options.departments.map(item => item.name)])].sort()
  const jobRoles = [...new Set([...suggestedJobRoles, ...options.jobRoles.map(item => item.title)])].sort()
  return <><InstitutionNameField options={options} form={form} update={update} prefix={prefix} /><label className="field">Department / division<input list={`${prefix}-departments`} value={form.departmentName} onChange={event => update('departmentName', event.target.value)} placeholder="Type or choose a department" required /><datalist id={`${prefix}-departments`}>{departments.map(item => <option key={item} value={item} />)}</datalist></label><label className="field">Job role<input list={`${prefix}-roles`} value={form.jobRoleName} onChange={event => update('jobRoleName', event.target.value)} placeholder="Type or choose a job role" required /><datalist id={`${prefix}-roles`}>{jobRoles.map(item => <option key={item} value={item} />)}</datalist></label></>
}

function useResource<T>(path: string, token: string) {
  const [data, setData] = useState<T | null>(null); const [error, setError] = useState(''); const [revision, setRevision] = useState(0)
  useEffect(() => { let alive = true; setData(null); setError(''); api<T>(path, {}, token).then(value => alive && setData(value)).catch(reason => alive && setError(reason instanceof Error ? reason.message : 'Unable to load this page.')); return () => { alive = false } }, [path, revision, token])
  return { data, error, refresh: () => setRevision(value => value + 1) }
}
function useOptions() { const [options, setOptions] = useState<Options | null>(null); useEffect(() => { api<Options>('/onboarding/options').then(setOptions).catch(() => undefined) }, []); return options }
function useLightweightScene() { const [lightweight, setLightweight] = useState(false); useEffect(() => { const query = window.matchMedia('(max-width: 720px), (prefers-reduced-motion: reduce)'); const update = () => setLightweight(query.matches); update(); query.addEventListener('change', update); return () => query.removeEventListener('change', update) }, []); return lightweight }

export function App() {
  const [token, setToken] = useState<string | null>(() => localStorage.getItem('cc_token')); const [user, setUser] = useState<User | null>(null); const [mode, setMode] = useState<'landing' | 'login' | 'register' | 'onboarding' | 'app'>('landing'); const [toast, setToast] = useState<Toast | null>(null)
  const notify = (message: string, kind: Toast['kind'] = 'success') => { setToast({ message, kind }); window.setTimeout(() => setToast(null), 4200) }
  useEffect(() => { if (!token) return; api<User>('/me', {}, token).then(value => { setUser(value); setMode(value.onboardingComplete ? 'app' : 'onboarding') }).catch(() => { localStorage.removeItem('cc_token'); setToken(null); setMode('login') }) }, [token])
  const signedIn = (accessToken: string, value: User, needsOnboarding = false) => { localStorage.setItem('cc_token', accessToken); setToken(accessToken); setUser(value); setMode(needsOnboarding || !value.onboardingComplete ? 'onboarding' : 'app') }
  const logout = () => { localStorage.removeItem('cc_token'); setToken(null); setUser(null); setMode('landing'); notify('You have been signed out.') }
  return <div className="shell"><div className="noise" />{mode === 'landing' && <ImmersiveLanding onStart={() => setMode('login')} />}{mode === 'login' && <Login onBack={() => setMode('landing')} onRegister={() => setMode('register')} onSignedIn={signedIn} />}{mode === 'register' && <Register onBack={() => setMode('login')} onSignedIn={signedIn} />}{mode === 'onboarding' && token && user && <Onboarding token={token} user={user} onDone={next => { setUser(next); setMode('app'); notify('Your employee profile and learning plan are ready.') }} />}{mode === 'app' && token && user && <Portal token={token} user={user} onLogout={logout} notify={notify} />}{toast && <div className={`toast ${toast.kind === 'error' ? 'toast-error' : ''}`} role="status">{toast.message}</div>}</div>
}

function ImmersiveLanding({ onStart }: { onStart: () => void }) {
  const [progress, setProgress] = useState(0); const lightweight = useLightweightScene()
  useEffect(() => { const update = () => { const total = Math.max(1, document.documentElement.scrollHeight - window.innerHeight); setProgress(Math.min(1, Math.max(0, window.scrollY / total))) }; update(); window.addEventListener('scroll', update, { passive: true }); window.addEventListener('resize', update); return () => { window.removeEventListener('scroll', update); window.removeEventListener('resize', update) } }, [])
  return <main className="immersive-landing"><div className="immersive-background" aria-hidden="true">{lightweight ? <div className="immersive-fallback"><div className="fallback-orbit" /><div className="fallback-globe" /></div> : <Suspense fallback={<div className="immersive-fallback"><div className="fallback-globe" /></div>}><ImmersiveLandingScene progress={progress} /></Suspense>}</div><header className="topbar landing-nav"><Brand /><nav className="toplinks" aria-label="Landing navigation"><a href="#workflow">How it works</a><a href="#employees">For employees</a><a href="#organizations">For organisations</a><button className="secondary nav-signin" onClick={onStart}>Login</button></nav></header><div className="landing-story"><section className="immersive-stage stage-intro" aria-labelledby="intro-title"><div className="story-copy"><div className="eyebrow">Ministry of Earth Sciences · Employee Development</div><h1 id="intro-title">Build capability.<br /><span className="gradient">Keep knowledge moving.</span></h1><p>Capacity Connect gives employees, trainers, experts, managers, and MoES institutions one practical system for verified workforce development.</p><div className="hero-actions"><button className="primary" onClick={onStart}>Get Started <ChevronRight size={17} /></button><a className="secondary" href="#workflow">See the workflow</a></div><div className="immersive-stats">{[['Role-based', 'Training'], ['Evidence-led', 'Verification'], ['Personalised', 'Schedules']].map(([number, label]) => <div className="stat" key={label}><strong>{number}</strong><span>{label}</span></div>)}</div></div><div className="scroll-cue"><span>Scroll to explore</span><i /></div></section><section className="immersive-stage stage-network" id="workflow"><div className="story-panel"><div className="eyebrow">01 · One clear workflow</div><h2>From role to<br />verified skill.</h2><p>Register, complete an employee profile, identify job-based gaps, follow a personal schedule, complete learning, submit evidence, receive expert verification, and earn a competency certificate.</p><a className="inline-action" href="#employees">See employee benefits <ChevronRight size={15} /></a></div><div className="stage-index">01 / 03</div></section><section className="immersive-stage stage-path" id="employees"><div className="story-panel"><div className="eyebrow">02 · Useful every day</div><h2>Training that fits<br />real work.</h2><p>Employees see their next lesson, assessment, mentor support, job-specific gaps, and available learning time—without decorative distractions.</p><button className="inline-action button-link" onClick={onStart}>Create an employee account <ChevronRight size={15} /></button></div><div className="stage-index">02 / 03</div></section><section className="immersive-stage stage-analytics" id="organizations"><div className="story-panel analytics-panel"><div className="eyebrow">03 · Organisational readiness</div><h2>Development leaders<br />can act on.</h2><p>Managers and administrators see clear capability gaps, training priorities, evidence progress, and knowledge-continuity signals—with humans accountable for every decision.</p><button className="primary" onClick={onStart}>Login to Capacity Connect <ChevronRight size={16} /></button></div><div className="stage-index">03 / 03</div><footer className="immersive-footer">Capacity Connect · Employee development for a climate-ready organisation</footer></section></div></main>
}

function Login({ onBack, onRegister, onSignedIn }: { onBack: () => void; onRegister: () => void; onSignedIn: (token: string, user: User) => void }) {
  const [email, setEmail] = useState('learner@capacityconnect.in'); const [password, setPassword] = useState('Demo@123'); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { const result = await api<{ accessToken: string; user: User }>('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); onSignedIn(result.accessToken, result.user) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not sign in.') } finally { setBusy(false) } }
  return <main className="auth-wrap"><form onSubmit={submit} className="glass auth-card"><button type="button" className="text-button" onClick={onBack}>← Back to home</button><div className="eyebrow">Secure employee access</div><h1>Welcome back</h1><p>Sign in to continue your role-based development workspace.</p><label className="field">Official email<input type="email" value={email} onChange={e => setEmail(e.target.value)} autoComplete="email" required /></label><label className="field">Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required /></label>{error && <div className="error">{error}</div>}<button className="primary full" disabled={busy}>{busy ? 'Signing in…' : 'Login'} <ChevronRight size={16} /></button><button type="button" className="secondary full" onClick={onRegister}>Create employee account</button><div className="demo-box"><b>Demo employee</b><br /><code>learner@capacityconnect.in</code> · <code>Demo@123</code></div></form></main>
}

function Register({ onBack, onSignedIn }: { onBack: () => void; onSignedIn: (token: string, user: User, needsOnboarding: boolean) => void }) {
  const [step, setStep] = useState(1); const [fullName, setFullName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [role, setRole] = useState('Employee/New Trainee'); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const submit = async (event: FormEvent) => { event.preventDefault(); if (step === 1) { setStep(2); return } setBusy(true); setError(''); try { const result = await api<{ accessToken: string; user: User; needsOnboarding: boolean }>('/auth/register', { method: 'POST', body: JSON.stringify({ fullName, officialEmail: email, password, role }) }); onSignedIn(result.accessToken, result.user, true) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not create the account.') } finally { setBusy(false) } }
  return <main className="auth-wrap"><form onSubmit={submit} className="glass auth-card"><button type="button" className="text-button" onClick={step === 1 ? onBack : () => setStep(1)}>← {step === 1 ? 'Back to login' : 'Back'}</button><div className="step-progress"><i className={step >= 1 ? 'done' : ''} /><i className={step >= 2 ? 'done' : ''} /></div><div className="eyebrow">Create your account · Step {step} of 2</div>{step === 1 ? <><h1>Start with the basics</h1><p>Use your official work email. You will complete your employee profile next.</p><label className="field">Full name<input value={fullName} onChange={e => setFullName(e.target.value)} required /></label><label className="field">Official email<input type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label><label className="field">Password<input type="password" minLength={8} value={password} onChange={e => setPassword(e.target.value)} required /></label><button className="primary full">Continue <ChevronRight size={16} /></button></> : <><h1>Choose your account role</h1><p>This controls the workspaces available after your profile is complete.</p><div className="role-choice">{['Employee/New Trainee', 'Trainer', 'Expert/Mentor', 'Manager', 'Administrator'].map(item => <label key={item}><input type="radio" name="role" checked={role === item} value={item} onChange={() => setRole(item)} /> <span><b>{item}</b><small>{item === 'Employee/New Trainee' ? 'Follow a job-based training plan.' : 'Use role-specific development tools.'}</small></span></label>)}</div>{error && <div className="error">{error}</div>}<button className="primary full" disabled={busy}>{busy ? 'Creating account…' : 'Create account'} <ChevronRight size={16} /></button></>}</form></main>
}

function OnboardingLegacy({ token, user, onDone }: { token: string; user: User; onDone: (user: User) => void }) {
  const options = useOptions(); const [step, setStep] = useState(1); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const [form, setForm] = useState<any>({ fullName: user.name, employeeId: user.employeeId.startsWith('NEW-') ? '' : user.employeeId, institutionId: '', departmentId: '', jobRoleId: '', designation: '', workLocation: '', employmentType: 'Permanent', joiningDate: '', experienceYears: 0, reportingManager: '', responsibilities: '', certificationsResume: '', languagesKnown: ['English'], targetSkills: [], developmentGoals: '', availableTimes: { days: [], time: '' }, hoursPerWeek: 4, preferredTrainingLanguage: 'English', learningPreference: 'Blended', skills: [] })
  if (!options) return <main className="auth-wrap"><Loading /></main>
  const update = (key: string, value: unknown) => setForm((current: any) => ({ ...current, [key]: value })); const departments = options.departments.filter(item => !form.institutionId || item.institutionId === Number(form.institutionId))
  const toggleDay = (day: string) => { const days = form.availableTimes.days.includes(day) ? form.availableTimes.days.filter((item: string) => item !== day) : [...form.availableTimes.days, day]; update('availableTimes', { ...form.availableTimes, days }) }
  const toggleSkill = (skill: { id: number; name: string }) => { const exists = form.skills.find((item: any) => item.skillId === skill.id); update('skills', exists ? form.skills.filter((item: any) => item.skillId !== skill.id) : [...form.skills, { skillId: skill.id, name: skill.name, level: 1 }]) }
  const level = (id: number, value: number) => update('skills', form.skills.map((item: any) => item.skillId === id ? { ...item, level: value } : item))
  const save = async () => { setSaving(true); setError(''); try { const result = await api<{ onboardingComplete: boolean }>('/onboarding', { method: 'PUT', body: JSON.stringify(form) }, token); if (!result.onboardingComplete) { setError('Please complete workplace details and choose at least one available learning time.'); return } onDone(await api<User>('/me', {}, token)) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not save your profile.') } finally { setSaving(false) } }
  return <main className="onboarding-wrap"><section className="onboarding-card glass"><Brand /><div className="step-progress three"><i className={step >= 1 ? 'done' : ''} /><i className={step >= 2 ? 'done' : ''} /><i className={step >= 3 ? 'done' : ''} /></div><div className="eyebrow">Employee profile · Step {step} of 3</div><h1>{step === 1 ? 'Your workplace' : step === 2 ? 'Your current capability' : 'Your learning preferences'}</h1><p>{step === 1 ? 'Tell us about your role. We do not ask for Aadhaar, salary, caste, or home address.' : step === 2 ? 'Select the skills you already use and rate your current confidence honestly.' : 'A realistic schedule works around your availability and development goals.'}</p>{step === 1 && <div className="form-grid"><label className="field">Full name<input value={form.fullName} onChange={e => update('fullName', e.target.value)} required /></label><label className="field">Employee ID<input value={form.employeeId} onChange={e => update('employeeId', e.target.value)} required /></label><label className="field">Institution<select value={form.institutionId} onChange={e => update('institutionId', e.target.value)} required><option value="">Select institution</option>{options.institutions.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field">Department / division<select value={form.departmentId} onChange={e => update('departmentId', e.target.value)} required><option value="">Select department</option>{departments.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field">Job role<select value={form.jobRoleId} onChange={e => update('jobRoleId', e.target.value)} required><option value="">Select job role</option>{options.jobRoles.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label className="field">Designation<input value={form.designation} onChange={e => update('designation', e.target.value)} placeholder="e.g. Weather Officer" required /></label><label className="field">Work location<input value={form.workLocation} onChange={e => update('workLocation', e.target.value)} required /></label><label className="field">Employment type<select value={form.employmentType} onChange={e => update('employmentType', e.target.value)}><option>Permanent</option><option>Contract</option><option>New trainee</option></select></label><label className="field">Joining date<input type="date" value={form.joiningDate} onChange={e => update('joiningDate', e.target.value)} /></label><label className="field">Years of experience<input type="number" min="0" max="50" value={form.experienceYears} onChange={e => update('experienceYears', Number(e.target.value))} /></label><label className="field">Reporting manager<input value={form.reportingManager} onChange={e => update('reportingManager', e.target.value)} /></label><label className="field full-span">Current responsibilities<textarea value={form.responsibilities} onChange={e => update('responsibilities', e.target.value)} placeholder="Describe your operational responsibilities in simple terms." /></label></div>}{step === 2 && <><div className="skill-picker">{options.skills.map(skill => { const chosen = form.skills.find((item: any) => item.skillId === skill.id); return <div className={`skill-option ${chosen ? 'selected' : ''}`} key={skill.id}><label><input type="checkbox" checked={Boolean(chosen)} onChange={() => toggleSkill(skill)} /> <span><b>{skill.name}</b><small>{skill.domain}</small></span></label>{chosen && <select value={chosen.level} onChange={e => level(skill.id, Number(e.target.value))}>{[1, 2, 3, 4, 5].map(value => <option value={value} key={value}>Level {value}</option>)}</select>}</div> })}</div><label className="field">Certifications and résumé summary<textarea value={form.certificationsResume} onChange={e => update('certificationsResume', e.target.value)} placeholder="List relevant certificates, training, projects, or a résumé summary." /></label></>}{step === 3 && <div className="form-grid"><label className="field">Languages known<input value={form.languagesKnown.join(', ')} onChange={e => update('languagesKnown', e.target.value.split(',').map(item => item.trim()).filter(Boolean))} /></label><label className="field">Target skills<input value={form.targetSkills.join(', ')} onChange={e => update('targetSkills', e.target.value.split(',').map(item => item.trim()).filter(Boolean))} placeholder="e.g. Cyclone Forecasting" /></label><label className="field full-span">Professional-development goals<textarea value={form.developmentGoals} onChange={e => update('developmentGoals', e.target.value)} placeholder="What would you like to become confident doing?" /></label><fieldset className="field full-span"><legend>Available learning days</legend><div className="day-picker">{['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].map(day => <button type="button" className={form.availableTimes.days.includes(day) ? 'small-btn selected' : 'small-btn'} onClick={() => toggleDay(day)} key={day}>{day.slice(0, 3)}</button>)}</div></fieldset><label className="field">Available time<select value={form.availableTimes.time} onChange={e => update('availableTimes', { ...form.availableTimes, time: e.target.value })} required><option value="">Choose a time</option><option>08:00–10:00</option><option>12:00–14:00</option><option>16:00–18:00</option><option>Flexible</option></select></label><label className="field">Hours available each week<input type="number" min="1" max="40" value={form.hoursPerWeek} onChange={e => update('hoursPerWeek', Number(e.target.value))} /></label><label className="field">Preferred training language<select value={form.preferredTrainingLanguage} onChange={e => update('preferredTrainingLanguage', e.target.value)}><option>English</option><option>Hindi</option><option>Malayalam</option></select></label><label className="field">Learning preference<select value={form.learningPreference} onChange={e => update('learningPreference', e.target.value)}><option>Online</option><option>Classroom</option><option>Blended</option></select></label></div>}{error && <div className="error">{error}</div>}<footer className="onboarding-actions"><button className="secondary" disabled={step === 1} onClick={() => setStep(value => value - 1)}>Back</button>{step < 3 ? <><button className="text-button" type="button" onClick={() => setStep(value => value + 1)}>Skip for now</button><button className="primary" type="button" onClick={() => setStep(value => value + 1)}>Continue <ChevronRight size={16} /></button></> : <button className="primary" type="button" onClick={save} disabled={saving}>{saving ? 'Saving…' : 'Save and build my plan'} <ChevronRight size={16} /></button>}</footer></section></main>
}

function Onboarding({ token, user, onDone }: { token: string; user: User; onDone: (user: User) => void }) {
  let options = useOptions()
  const [step, setStep] = useState(1)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [form, setForm] = useState<any>({ fullName: user.name, employeeId: user.employeeId.startsWith('NEW-') ? '' : user.employeeId, institutionId: '', institutionName: '', departmentName: '', jobRoleName: '', designation: '', workLocation: '', employmentType: 'Permanent', joiningDate: '', experienceYears: 0, reportingManager: '', responsibilities: '', certificationsResume: '', languagesKnown: ['English'], targetSkills: [], developmentGoals: '', availableTimes: { days: [], time: '' }, hoursPerWeek: 4, preferredTrainingLanguage: 'English', learningPreference: 'Blended', skills: [] })
  if (!options) return <main className="auth-wrap"><Loading /></main>
  const selectedRoleSkills = roleSpecificSkills[form.jobRoleName.trim().toLowerCase()]
  if (selectedRoleSkills) options = { ...options, skills: selectedRoleSkills }
  const update = (key: string, value: unknown) => setForm((current: any) => ({ ...current, [key]: value }))
  const toggleDay = (day: string) => update('availableTimes', { ...form.availableTimes, days: form.availableTimes.days.includes(day) ? form.availableTimes.days.filter((item: string) => item !== day) : [...form.availableTimes.days, day] })
  const toggleSkill = (skill: { id: number; name: string }) => { const selected = form.skills.some((item: any) => item.skillId === skill.id); update('skills', selected ? form.skills.filter((item: any) => item.skillId !== skill.id) : [...form.skills, { skillId: skill.id, name: skill.name, level: 1 }]) }
  const setLevel = (id: number, level: number) => update('skills', form.skills.map((item: any) => item.skillId === id ? { ...item, level } : item))
  const missingWorkplace = () => [['Employee ID', form.employeeId], ['Institution / organisation', form.institutionName], ['Department / division', form.departmentName], ['Job role', form.jobRoleName], ['Designation', form.designation], ['Work location', form.workLocation], ['Available time', form.availableTimes.time]].filter(([, value]) => !String(value || '').trim()).map(([label]) => label)
  const save = async () => { const missing = missingWorkplace(); if (missing.length) { setError(`Please complete: ${missing.join(', ')}.`); setStep(1); return } setSaving(true); setError(''); try { const result = await api<{ onboardingComplete: boolean }>('/onboarding', { method: 'PUT', body: JSON.stringify(form) }, token); if (!result.onboardingComplete) { setError('Your workplace details still need attention. Please check the highlighted fields.'); setStep(1); return } onDone(await api<User>('/me', {}, token)) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Could not save your profile.') } finally { setSaving(false) } }
  return <main className="onboarding-wrap"><section className="onboarding-card glass"><Brand /><div className="step-progress three"><i className={step >= 1 ? 'done' : ''} /><i className={step >= 2 ? 'done' : ''} /><i className={step >= 3 ? 'done' : ''} /></div><div className="eyebrow">Employee profile · Step {step} of 3</div><h1>{step === 1 ? 'Your workplace' : step === 2 ? 'Your current capability' : 'Your learning preferences'}</h1>{step === 1 && <><p>Type your department and job role, or choose a useful suggestion. We do not request Aadhaar, salary, caste, or home address.</p><div className="form-grid"><label className="field">Full name<input value={form.fullName} onChange={event => update('fullName', event.target.value)} required /></label><label className="field">Employee ID<input value={form.employeeId} onChange={event => update('employeeId', event.target.value)} required /></label><label className="field">Institution<select value={form.institutionId} onChange={event => update('institutionId', event.target.value)} required><option value="">Select institution</option>{options.institutions.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><RoleDetailsFields options={options} form={form} update={update} prefix="onboarding" /><label className="field">Designation<input value={form.designation} onChange={event => update('designation', event.target.value)} placeholder="e.g. Junior Data Analyst" required /></label><label className="field">Work location<input value={form.workLocation} onChange={event => update('workLocation', event.target.value)} required /></label><label className="field">Employment type<select value={form.employmentType} onChange={event => update('employmentType', event.target.value)}><option>Permanent</option><option>Contract</option><option>New trainee</option></select></label><label className="field">Joining date<input type="date" value={form.joiningDate} onChange={event => update('joiningDate', event.target.value)} /></label><label className="field">Years of experience<input type="number" min="0" max="50" value={form.experienceYears} onChange={event => update('experienceYears', Number(event.target.value))} /></label><label className="field">Reporting manager<input value={form.reportingManager} onChange={event => update('reportingManager', event.target.value)} /></label><label className="field full-span">Current responsibilities<textarea value={form.responsibilities} onChange={event => update('responsibilities', event.target.value)} placeholder="Describe your operational responsibilities in simple terms." /></label></div></>}{step === 2 && <><p>Select skills you already use and rate your current confidence honestly.</p><div className="skill-picker">{options.skills.map(skill => { const selected = form.skills.find((item: any) => item.skillId === skill.id); return <div className={`skill-option ${selected ? 'selected' : ''}`} key={skill.id}><label><input type="checkbox" checked={Boolean(selected)} onChange={() => toggleSkill(skill)} /><span><b>{skill.name}</b><small>{skill.domain}</small></span></label>{selected && <select value={selected.level} onChange={event => setLevel(skill.id, Number(event.target.value))}>{[1, 2, 3, 4, 5].map(level => <option value={level} key={level}>Level {level}</option>)}</select>}</div> })}</div><label className="field">Certifications and résumé summary<textarea value={form.certificationsResume} onChange={event => update('certificationsResume', event.target.value)} placeholder="List relevant certificates, training, projects, or a résumé summary." /></label></>}{step === 3 && <><p>A realistic schedule works around your availability and development goals.</p><div className="form-grid"><label className="field">Languages known<input value={form.languagesKnown.join(', ')} onChange={event => update('languagesKnown', event.target.value.split(',').map(item => item.trim()).filter(Boolean))} /></label><label className="field">Target skills<input value={form.targetSkills.join(', ')} onChange={event => update('targetSkills', event.target.value.split(',').map(item => item.trim()).filter(Boolean))} placeholder="e.g. Data Visualisation" /></label><label className="field full-span">Professional-development goals<textarea value={form.developmentGoals} onChange={event => update('developmentGoals', event.target.value)} placeholder="What would you like to become confident doing?" /></label><fieldset className="field full-span"><legend>Available learning days</legend><div className="day-picker">{['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].map(day => <button type="button" className={form.availableTimes.days.includes(day) ? 'small-btn selected' : 'small-btn'} onClick={() => toggleDay(day)} key={day}>{day.slice(0, 3)}</button>)}</div></fieldset><label className="field">Available time<select value={form.availableTimes.time} onChange={event => update('availableTimes', { ...form.availableTimes, time: event.target.value })} required><option value="">Choose a time</option><option>08:00–10:00</option><option>12:00–14:00</option><option>16:00–18:00</option><option>Flexible</option></select></label><label className="field">Hours available each week<input type="number" min="1" max="40" value={form.hoursPerWeek} onChange={event => update('hoursPerWeek', Number(event.target.value))} /></label><label className="field">Training language<select value={form.preferredTrainingLanguage} onChange={event => update('preferredTrainingLanguage', event.target.value)}><option>English</option><option>Hindi</option><option>Malayalam</option></select></label><label className="field">Learning preference<select value={form.learningPreference} onChange={event => update('learningPreference', event.target.value)}><option>Online</option><option>Classroom</option><option>Blended</option></select></label></div></>}{error && <div className="error">{error}</div>}<footer className="onboarding-actions"><button className="secondary" type="button" disabled={step === 1} onClick={() => setStep(current => current - 1)}>Back</button>{step < 3 ? <><button className="text-button" type="button" onClick={() => setStep(current => current + 1)}>Skip for now</button><button className="primary" type="button" onClick={() => setStep(current => current + 1)}>Continue <ChevronRight size={16} /></button></> : <button className="primary" type="button" onClick={save} disabled={saving}>{saving ? 'Saving…' : 'Save and build my plan'} <ChevronRight size={16} /></button>}</footer></section></main>
}

function Portal({ token, user, onLogout, notify }: { token: string; user: User; onLogout: () => void; notify: (message: string, kind?: Toast['kind']) => void }) {
  const kind = roleKind(user.role)
  const nav: Page[] = kind === 'employee' ? ['dashboard', 'profile', 'gaps', 'plan', 'courses', 'assessments', 'mentors', 'knowledge', 'certificates'] : kind === 'trainer' ? ['dashboard', 'profile', 'trainer', 'reviews', 'courses', 'assessments', 'knowledge'] : kind === 'manager' ? ['dashboard', 'profile', 'manager', 'gaps', 'plan', 'knowledge'] : kind === 'admin' ? ['dashboard', 'profile', 'admin', 'reviews', 'courses', 'knowledge', 'certificates'] : ['dashboard', 'profile', 'reviews', 'mentors', 'knowledge', 'certificates']
  const [page, setPage] = useState<Page>('dashboard')
  const [search, setSearch] = useState('')
  const openSearch = (event: FormEvent) => {
    event.preventDefault()
    const term = search.toLowerCase()
    setPage(term.includes('mentor') ? 'mentors' : term.includes('assessment') ? 'assessments' : term.includes('skill') || term.includes('gap') ? 'gaps' : 'courses')
    notify(`Showing the closest workspace for “${search}”.`)
  }
  return <div className="app-layout"><aside className="sidebar"><Brand /><nav className="nav" aria-label="Main navigation">{nav.map(item => { const Icon = icons[item]; return <button key={item} className={page === item ? 'active' : ''} onClick={() => setPage(item)}><Icon size={18} /><span>{labels[item].label}</span></button> })}</nav><div className="sidebar-bottom"><button className="nav" onClick={onLogout}><LogOut size={17} /><span>Sign out</span></button></div></aside><main className="main"><header className="app-topbar"><div className="mobile-brand"><Brand /></div><form className="search" onSubmit={openSearch}><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search courses, skills, or mentors" aria-label="Search workspaces" /><kbd>Enter</kbd></form><div className="user-menu"><Bell size={18} /><button className="profile-trigger" onClick={() => setPage('profile')} aria-label="Open my profile"><div><b>{user.name}</b><br /><small>{user.role.replace('Employee/Learner', 'Employee').replace('Subject-Matter Expert/Mentor', 'Expert')}</small></div><div className="avatar">{user.name.split(' ').map(item => item[0]).join('').slice(0, 2)}</div></button></div></header>{page === 'dashboard' && <Dashboard token={token} user={user} go={setPage} />}{page === 'profile' && <Profile token={token} user={user} notify={notify} />}{page === 'gaps' && <SkillGaps token={token} notify={notify} go={setPage} />}{page === 'plan' && <LearningPlan token={token} notify={notify} />}{page === 'courses' && <Courses token={token} notify={notify} />}{page === 'assessments' && <Assessments token={token} notify={notify} />}{page === 'mentors' && <Mentors token={token} notify={notify} />}{page === 'knowledge' && <Knowledge token={token} />}{page === 'certificates' && <Certificates token={token} />}{page === 'reviews' && <Reviews token={token} notify={notify} />}{page === 'trainer' && <Trainer token={token} notify={notify} />}{page === 'manager' && <Manager token={token} notify={notify} />}{page === 'admin' && <Admin token={token} />}</main></div>
}

function ProfileLegacy({ token, user, notify }: { token: string; user: User; notify: (message: string, kind?: Toast['kind']) => void }) {
  const details = useResource<any>('/onboarding', token)
  const options = useOptions()
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState<any>({ fullName: user.name, employeeId: user.employeeId, institutionId: '', departmentId: '', jobRoleId: '', designation: '', workLocation: '', employmentType: 'Permanent', joiningDate: '', reportingManager: '', responsibilities: '', certificationsResume: '', languagesKnown: [], targetSkills: [], developmentGoals: '', availableTimes: { days: [], time: '' }, hoursPerWeek: 4, preferredTrainingLanguage: 'English', learningPreference: 'Blended' })
  useEffect(() => {
    if (!details.data || !options) return
    const record = details.data.user || {}
    const profile = details.data.profile || {}
    const institution = options.institutions.find(item => item.name === record.institution)
    const department = options.departments.find(item => item.name === record.department && (!institution || item.institutionId === institution.id))
    const jobRole = options.jobRoles.find(item => item.title === record.jobRole)
    setForm({ fullName: record.name || user.name, employeeId: record.employeeId || user.employeeId, institutionId: institution?.id || '', departmentId: department?.id || '', jobRoleId: jobRole?.id || '', designation: profile.designation || '', workLocation: profile.workLocation || '', employmentType: profile.employmentType || 'Permanent', joiningDate: profile.joiningDate || '', reportingManager: profile.reportingManager || '', responsibilities: profile.responsibilities || '', certificationsResume: profile.certificationsResume || '', languagesKnown: profile.languagesKnown || [], targetSkills: profile.targetSkills || [], developmentGoals: profile.developmentGoals || '', availableTimes: profile.availableTimes || { days: [], time: '' }, hoursPerWeek: profile.hoursPerWeek || 4, preferredTrainingLanguage: profile.preferredTrainingLanguage || 'English', learningPreference: profile.learningPreference || 'Blended' })
  }, [details.data, options, user.employeeId, user.name])
  if (!details.data || !options) return <div className="page"><Loading error={details.error} retry={details.refresh} /></div>
  const update = (key: string, value: any) => setForm((current: any) => ({ ...current, [key]: value }))
  const departments = options.departments.filter(item => item.institutionId === Number(form.institutionId))
  const toggleDay = (day: string) => update('availableTimes', { ...form.availableTimes, days: form.availableTimes.days.includes(day) ? form.availableTimes.days.filter((item: string) => item !== day) : [...form.availableTimes.days, day] })
  const save = async (event: FormEvent) => { event.preventDefault(); setSaving(true); try { const result = await api<any>('/onboarding', { method: 'PUT', body: JSON.stringify(form) }, token); notify(result.message); details.refresh() } catch (reason) { notify(reason instanceof Error ? reason.message : 'Could not save your profile.', 'error') } finally { setSaving(false) } }
  return <div className="page"><PageHeader page="profile" /><form onSubmit={save}><section className="panel profile-intro"><h2>Personal and employment details</h2><p className="panel-sub">These details make your recommendations relevant to your role. Capacity Connect does not collect Aadhaar, salary, caste, home address, or other sensitive personal information.</p><div className="form-grid"><label className="field">Full name<input value={form.fullName} onChange={e => update('fullName', e.target.value)} required /></label><label className="field">Official work email<input value={details.data.user.email || user.email} disabled /></label><label className="field">Employee ID<input value={form.employeeId} onChange={e => update('employeeId', e.target.value)} required /></label></div></section><section className="panel" style={{ marginTop: 16 }}><h2>Your workplace</h2><div className="form-grid"><label className="field">Institution<select value={form.institutionId} onChange={e => { update('institutionId', e.target.value); update('departmentId', '') }} required><option value="">Select institution</option>{options.institutions.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field">Department / division<select value={form.departmentId} onChange={e => update('departmentId', e.target.value)} required><option value="">Select department</option>{departments.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="field">Job role<select value={form.jobRoleId} onChange={e => update('jobRoleId', e.target.value)} required><option value="">Select job role</option>{options.jobRoles.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label className="field">Designation<input value={form.designation} onChange={e => update('designation', e.target.value)} required /></label><label className="field">Work location<input value={form.workLocation} onChange={e => update('workLocation', e.target.value)} required /></label><label className="field">Employment type<select value={form.employmentType} onChange={e => update('employmentType', e.target.value)}><option>Permanent</option><option>Contract</option><option>New trainee</option></select></label><label className="field">Joining date<input type="date" value={form.joiningDate} onChange={e => update('joiningDate', e.target.value)} /></label><label className="field">Reporting manager<input value={form.reportingManager} onChange={e => update('reportingManager', e.target.value)} /></label><label className="field full-span">Current responsibilities<textarea value={form.responsibilities} onChange={e => update('responsibilities', e.target.value)} placeholder="Describe your operational responsibilities." /></label></div></section><section className="panel" style={{ marginTop: 16 }}><h2>Development preferences</h2><div className="form-grid"><label className="field">Languages known<input value={form.languagesKnown.join(', ')} onChange={e => update('languagesKnown', e.target.value.split(',').map(item => item.trim()).filter(Boolean))} placeholder="e.g. English, Hindi" /></label><label className="field">Target skills<input value={form.targetSkills.join(', ')} onChange={e => update('targetSkills', e.target.value.split(',').map(item => item.trim()).filter(Boolean))} placeholder="e.g. Cyclone Forecasting" /></label><label className="field full-span">Development goals<textarea value={form.developmentGoals} onChange={e => update('developmentGoals', e.target.value)} placeholder="What would you like to become confident doing?" /></label><label className="field full-span">Certifications or résumé summary<textarea value={form.certificationsResume} onChange={e => update('certificationsResume', e.target.value)} placeholder="Relevant certificates, training, and projects." /></label><fieldset className="field full-span"><legend>Available learning days</legend><div className="day-picker">{['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].map(day => <button type="button" className={form.availableTimes.days.includes(day) ? 'small-btn selected' : 'small-btn'} onClick={() => toggleDay(day)} key={day}>{day.slice(0, 3)}</button>)}</div></fieldset><label className="field">Available time<select value={form.availableTimes.time} onChange={e => update('availableTimes', { ...form.availableTimes, time: e.target.value })} required><option value="">Choose a time</option><option>08:00–10:00</option><option>12:00–14:00</option><option>16:00–18:00</option><option>Flexible</option></select></label><label className="field">Hours available each week<input type="number" min="1" max="40" value={form.hoursPerWeek} onChange={e => update('hoursPerWeek', Number(e.target.value))} /></label><label className="field">Training language<select value={form.preferredTrainingLanguage} onChange={e => update('preferredTrainingLanguage', e.target.value)}><option>English</option><option>Hindi</option><option>Malayalam</option></select></label><label className="field">Learning preference<select value={form.learningPreference} onChange={e => update('learningPreference', e.target.value)}><option>Online</option><option>Classroom</option><option>Blended</option></select></label></div><button className="primary" disabled={saving}>{saving ? 'Saving profile…' : 'Save profile'} <ChevronRight size={16} /></button></section></form></div>
}

